    let s01 = mix(s001, s101, pd.x);
    let s10 = mix(s010, s110, pd.x);
    let s11 = mix(s011, s111, pd.x);
    let s0 = mix(s00, s10, pd.y);
    let s1 = mix(s01, s11, pd.y);
    return mix(s0, s1, pd.z);
