    let y = load_tPreviousLevel(p + vec2<i32>(-1, 0), size);
    // the 2x2 block this texel covers, as the GLSL reads it (rows p and p - 1: both store rows in the same order)
    let z = load_tPreviousLevel(p + vec2<i32>(-1, -1), size);
